 const [data,setData]=useState<Data|null>(null),[auth,setAuth]=useState(""),[page,setPage]=useState("create"),[busy,setBusy]=useState(""),[toast,setToast]=useState(""),[mobile,setMobile]=useState(false);
 const [files,setFiles]=useState<Record<string,string>>({}),[options,setOptions]=useState(initial),[prompt,setPrompt]=useState(""),[headPrompt,setHeadPrompt]=useState(""),[note,setNote]=useState(""),[notes,setNotes]=useState(""),[advanced,setAdvanced]=useState(false),[picker,setPicker]=useState(""),[authMode,setAuthMode]=useState("");
 const [menu,setMenu]=useState(""),[panel,setPanel]=useState(false),[viewer,setViewer]=useState<number|null>(null),[tab,setTab]=useState("creations"),dock=useRef<HTMLDivElement>(null);
