 const [refining,setRefining]=useState<Refining|null>(null),[refineProgress,setRefineProgress]=useState<{phase:string;chars:number;started:number}|null>(null);
 const [progress,setProgress]=useState<{phase:string;chars:number;started:number}|null>(null),[promptError,setPromptError]=useState(""),[,setTick]=useState(0);
 const [filter,setFilter]=useState("Todos"),[search,setSearch]=useState(""),[libraryModel,setLibraryModel]=useState("Referências"),[category,setCategory]=useState("Outras"),[accounts,setAccounts]=useState<any[]>([]),[review,setReview]=useState<any[]>([]);
 const [member,setMember]=useState({email:"",name:"",budget:100,concurrent:1,active:true}),[configForm,setConfigForm]=useState<any>({runninghubKey:"",openaiKey:"",model:"gpt-6.1-sol",baseCost:10,promptCost:1,globalLimit:2,template:""});
 const uploadRef=useRef<HTMLInputElement>(null),target=useRef("scene"),requestKey=useRef<string|null>(null);
