 useEffect(()=>{if(!progress&&!refineProgress&&!running.length)return;const t=setInterval(()=>setTick(n=>n+1),1000);return()=>clearInterval(t);},[progress,refineProgress,running.length]);
 // Popovers in the composer close on any click outside it.
