 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(""),7000);return()=>clearTimeout(t);},[toast]);
 useEffect(()=>{if(!data||busy)return;const pending=data.jobs.filter(j=>j.remote_id&&["QUEUED","RUNNING"].includes(j.state));if(!pending.length)return;let stopped=false;const t=setTimeout(async()=>{try{for(const j of pending)if(!stopped)await api(`jobs/${j.id}`,{});if(!stopped)await refresh();}catch(e:any){if(!stopped)setToast(e.message);}},9000);return()=>{stopped=true;clearTimeout(t);};},[data,busy]);
 useEffect(()=>{if(page==="agents"&&data?.account.role==="admin")api("admin/agents").then(r=>setAgents(r.agents)).catch(e=>setToast(e.message));},[page,data?.account.role]);
