 function chooseUpload(slot:string){target.current=slot;uploadRef.current?.click();}
 const priceOf=(o:any)=>data?data.config.baseCost*Number(o.count||1)*(1+Number(o.head!==false)+Number(o.tattoo===true)+(o.quality==="4K"?2:o.quality==="2K"?1:0)):0;
 const cost=priceOf(options);
 const ready=!!data?.config.runninghub&&!!data?.config.template;
 async function run(kind:string){await action(kind,async()=>{
  if(kind==="generate")return generatePrompt();
  const storageKey=`priv8-request-${data?.account.id}-${kind}`;
  requestKey.current=sessionStorage.getItem(storageKey)||crypto.randomUUID();sessionStorage.setItem(storageKey,requestKey.current);
  try {
   const r=await api("jobs",{requestKey:requestKey.current,files,options,prompt,headPrompt,note});
   sessionStorage.removeItem(storageKey);requestKey.current=null;
   if(r.error)throw new Error(r.error);
   setToast(r.state==="QUEUED"?"Criação na fila. Ela aparece na sua galeria.":labels[r.state]||"Solicitação registrada.");
  }catch(e){throw e;}
  finally{await refresh().catch(()=>{});}
 });}
 // Each click is a new attempt: the server streams progress, so a lost answer is never silently reused.
 async function generatePrompt(){
  setPromptError("");setProgress({phase:"sending",chars:0,started:Date.now()});
  try{
   const response=await fetch("/api/prompts",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({requestKey:crypto.randomUUID(),files,options,note})});
   const r=await readApiStream(response,e=>{if(e.type==="progress")setProgress(p=>p&&{...p,phase:e.phase,chars:e.chars||0});});
   if(r.error)throw new Error(r.error);
   if(!r.result)throw new Error("O prompt ainda não está disponível. Confira o estado desta tentativa em Execuções.");
   setPrompt(r.result.prompt);setHeadPrompt(r.result.headPrompt||"");setNotes(r.result.notes||"");const view=/<image3>, the (back|left side|right side) view/i.exec(r.result.prompt)?.[1];if(view)setOptions(o=>({...o,view:view==="back"?"back":view==="left side"?"left":"right"}));setPanel(true);setToast("Prompt pronto para revisar.");
  }catch(e:any){setPromptError(e.message||"Não foi possível gerar o prompt.");}
  finally{setProgress(null);await refresh().catch(()=>{});}
 }
 const progressText=progress?`${progress.phase==="writing"?`Escrevendo o prompt · ${progress.chars.toLocaleString("pt-BR")} caracteres`:progress.phase==="thinking"?"Analisando as fotos":"Enviando as fotos"} · ${clock(Date.now()-progress.started)}`:"";
 const creations:Creation[]=data?data.jobs.filter(j=>j.kind==="image"&&j.state==="SUCCESS").flatMap(j=>{const r=result(j);return Array.isArray(r)?r.map((o:any,index:number)=>({o,index})).filter(({o})=>typeof o?.url==="string"&&!/\.(mp4|webm|mov)(\?|$)/i.test(o.url)).map(({o,index})=>({key:`${j.id}-${index}`,jobId:j.id,output:index,url:o.url as string,label:OUTPUT_LABELS[o.node]||"Resultado",created:j.created,scene:typeof j.scene==="string"?j.scene:null})):[];}):[];
 useEffect(()=>{if(viewer===null)return;const key=(e:KeyboardEvent)=>{if(e.key==="Escape")setViewer(null);if(e.key==="ArrowRight")setViewer(v=>v===null?v:Math.min(v+1,creations.length-1));if(e.key==="ArrowLeft")setViewer(v=>v===null?v:Math.max(v-1,0));};window.addEventListener("keydown",key);return()=>window.removeEventListener("keydown",key);},[viewer,creations.length]);
 const blocker=!data?"":!ready?"Integração pendente":!files.scene?"Escolha a foto da cena":!files.front?"Escolha a sua modelo":!prompt.trim()?"Gere ou escreva o prompt":cost>data.account.budget-data.used?"Créditos insuficientes":"";
