 const agent=agents.find(g=>g.id===agentId),agentText=agentDraft??agent?.prompt??"",agentDirty=agentDraft!==null&&agentDraft!==agent?.prompt;
 function pickAgent(id:string){if(id===agentId)return;if(agentDirty&&!confirm("Descartar as alterações não salvas deste agente?"))return;setAgentId(id);setAgentDraft(null);}
